#!/usr/bin/env python3
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
CODEC = ROOT / "linktools-ai/src/linktools/ai/runtime/state/_codec.py"
MIGRATION = ROOT / "linktools-ai/src/linktools/ai/runtime/state/_migration.py"
BINDING = ROOT / "linktools-ai/src/linktools/ai/agent/_binding.py"
BUILD = ROOT / "linktools-ai/scripts/build/persistence.py"
MANIFEST = ROOT / "linktools-ai/scripts/build/matrix/runtime-persistence-v1.json"
TEST = ROOT / "tests/ai/test_runtime_persistence_compatibility.py"


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected one match, found {count}")
    return text.replace(old, new, 1)


def patch_codec() -> None:
    text = CODEC.read_text(encoding="utf-8")

    old = '''DataclassDecoder = Callable[\n    [Mapping[str, object], "_VersionCodec"],\n    object,\n]\n\n\n@dataclass(frozen=True, slots=True)\nclass _VersionCodec:\n'''
    new = '''DataclassDecoder = Callable[\n    [Mapping[str, object], "_VersionCodec"],\n    object,\n]\nDataclassUpgrade = Callable[\n    [Mapping[str, object], "_VersionCodec"],\n    Mapping[str, object],\n]\n\n\n@dataclass(frozen=True, slots=True)\nclass _DataclassPersistenceContract:\n    fingerprints: Mapping[int, str]\n    upgrades: Mapping[int, DataclassUpgrade]\n    legacy_revision: int | None\n\n    @property\n    def current_revision(self) -> int:\n        return max(self.fingerprints)\n\n\n@dataclass(frozen=True, slots=True)\nclass _VersionCodec:\n'''
    text = replace_once(text, old, new, "dataclass contract")

    old = '''_CURRENT_CODEC = _VERSION_CODECS[CURRENT_DATA_VERSION]\n\n\ndef _dataclass_schema_descriptor(\n'''
    new = '''_CURRENT_CODEC = _VERSION_CODECS[CURRENT_DATA_VERSION]\n\n\ndef _build_v1_dataclass_persistence_contracts(\n) -> Mapping[str, _DataclassPersistenceContract]:\n    return MappingProxyType(\n        {\n            wire_id: _DataclassPersistenceContract(\n                fingerprints=MappingProxyType({1: fingerprint}),\n                upgrades=MappingProxyType({}),\n                legacy_revision=1,\n            )\n            for wire_id, fingerprint in _V1_SCHEMA_FINGERPRINTS.items()\n        }\n    )\n\n\n_V1_DATACLASS_PERSISTENCE = _build_v1_dataclass_persistence_contracts()\n_DATACLASS_PERSISTENCE_BY_VERSION: Mapping[\n    int, Mapping[str, _DataclassPersistenceContract]\n] = MappingProxyType({1: _V1_DATACLASS_PERSISTENCE})\n\n\ndef _dataclass_schema_descriptor(\n'''
    text = replace_once(text, old, new, "persistence registry")

    old = '''def encode_envelope(\n    value: Mapping[str, JsonValue],\n    *,\n    version: int = CURRENT_DATA_VERSION,\n) -> dict[str, JsonValue]:\n    if version != CURRENT_DATA_VERSION:\n        raise ValueError("only the frozen current data version may be written")\n    if not isinstance(value, Mapping):\n        raise TypeError("canonical data value must be a mapping")\n    return {"v": version, "value": dict(value)}\n'''
    new = '''def _dataclass_persistence_contract(\n    wire_id: str,\n    codec: _VersionCodec,\n) -> _DataclassPersistenceContract:\n    contracts = _DATACLASS_PERSISTENCE_BY_VERSION.get(codec.version)\n    if contracts is None:\n        raise AIError(ErrorCode.STORAGE_VERSION_UNSUPPORTED)\n    contract = contracts.get(wire_id)\n    if contract is None:\n        raise AIError(ErrorCode.STORAGE_VERSION_UNSUPPORTED)\n    return contract\n\n\ndef _encode_persisted_value(value: JsonValue, codec: _VersionCodec) -> JsonValue:\n    if isinstance(value, list):\n        return [_encode_persisted_value(item, codec) for item in value]\n    if not isinstance(value, Mapping):\n        return value\n    if "$dataclass" in value:\n        _require_exact_keys(value, frozenset({"$dataclass", "fields"}))\n        wire_id = value.get("$dataclass")\n        raw_fields = value.get("fields")\n        if not isinstance(wire_id, str) or not isinstance(raw_fields, Mapping):\n            raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n        contract = _dataclass_persistence_contract(wire_id, codec)\n        if codec.domain_types.get(wire_id) is None:\n            raise AIError(ErrorCode.STORAGE_VERSION_UNSUPPORTED)\n        return {\n            "$dataclass": wire_id,\n            "schema": contract.current_revision,\n            "fields": {\n                str(key): _encode_persisted_value(cast(JsonValue, item), codec)\n                for key, item in raw_fields.items()\n            },\n        }\n    return {\n        str(key): _encode_persisted_value(cast(JsonValue, item), codec)\n        for key, item in value.items()\n    }\n\n\ndef _apply_persisted_upgrades(\n    raw_fields: Mapping[str, object],\n    revision: int,\n    contract: _DataclassPersistenceContract,\n    codec: _VersionCodec,\n) -> Mapping[str, object]:\n    fields_value: Mapping[str, object] = dict(raw_fields)\n    current = revision\n    while current < contract.current_revision:\n        upgrade = contract.upgrades.get(current)\n        if upgrade is None:\n            raise AIError(ErrorCode.STORAGE_VERSION_UNSUPPORTED)\n        fields_value = dict(upgrade(fields_value, codec))\n        current += 1\n    return fields_value\n\n\ndef _normalize_persisted_dataclass(\n    value: Mapping[str, object],\n    codec: _VersionCodec,\n) -> JsonValue:\n    keys = frozenset(value)\n    if keys == frozenset({"$dataclass", "fields"}):\n        explicit_revision: object | None = None\n    elif keys == frozenset({"$dataclass", "schema", "fields"}):\n        explicit_revision = value.get("schema")\n    else:\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n\n    wire_id = value.get("$dataclass")\n    raw_fields = value.get("fields")\n    if not isinstance(wire_id, str) or not isinstance(raw_fields, Mapping):\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n    contract = _dataclass_persistence_contract(wire_id, codec)\n    if codec.domain_types.get(wire_id) is None:\n        raise AIError(ErrorCode.STORAGE_VERSION_UNSUPPORTED)\n\n    if explicit_revision is None:\n        revision = contract.legacy_revision\n        if revision is None:\n            raise AIError(ErrorCode.STORAGE_VERSION_UNSUPPORTED)\n    else:\n        if (\n            isinstance(explicit_revision, bool)\n            or not isinstance(explicit_revision, int)\n            or explicit_revision < 1\n        ):\n            raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n        revision = explicit_revision\n    if revision not in contract.fingerprints:\n        raise AIError(ErrorCode.STORAGE_VERSION_UNSUPPORTED)\n\n    normalized_fields = {\n        str(key): _normalize_persisted_value(cast(JsonValue, item), codec)\n        for key, item in raw_fields.items()\n    }\n    upgraded = _apply_persisted_upgrades(\n        normalized_fields, revision, contract, codec\n    )\n    return {\n        "$dataclass": wire_id,\n        "fields": cast(dict[str, JsonValue], dict(upgraded)),\n    }\n\n\ndef _normalize_persisted_value(value: JsonValue, codec: _VersionCodec) -> JsonValue:\n    if isinstance(value, list):\n        return [_normalize_persisted_value(item, codec) for item in value]\n    if not isinstance(value, Mapping):\n        return value\n    if "$dataclass" in value:\n        return _normalize_persisted_dataclass(value, codec)\n    return {\n        str(key): _normalize_persisted_value(cast(JsonValue, item), codec)\n        for key, item in value.items()\n    }\n\n\ndef _runtime_persistence_manifest() -> dict[str, JsonValue]:\n    contracts = _DATACLASS_PERSISTENCE_BY_VERSION[CURRENT_DATA_VERSION]\n    return {\n        "wire_version": CURRENT_DATA_VERSION,\n        "dataclasses": {\n            wire_id: {\n                "legacy_revision": contract.legacy_revision,\n                "revisions": {\n                    str(revision): fingerprint\n                    for revision, fingerprint in sorted(contract.fingerprints.items())\n                },\n            }\n            for wire_id, contract in sorted(contracts.items())\n        },\n        "enums": {\n            wire_id: sorted(cast(str, value) for value in values)\n            for wire_id, values in sorted(_V1_ENUM_VALUES.items())\n        },\n        "external": {\n            "agent_binding_snapshot": {"owner": "agent", "version": 1},\n            "model_message": {\n                "owner": "pydantic-ai",\n                "fixture": "runtime_model_messages_v1.json",\n            },\n        },\n    }\n\n\ndef encode_envelope(\n    value: Mapping[str, JsonValue],\n    *,\n    version: int = CURRENT_DATA_VERSION,\n) -> dict[str, JsonValue]:\n    if version != CURRENT_DATA_VERSION:\n        raise ValueError("only the frozen current data version may be written")\n    if not isinstance(value, Mapping):\n        raise TypeError("canonical data value must be a mapping")\n    codec = _VERSION_CODECS.get(version)\n    if codec is None:\n        raise AIError(ErrorCode.STORAGE_VERSION_UNSUPPORTED)\n    persisted = _encode_persisted_value(dict(value), codec)\n    if not isinstance(persisted, Mapping):\n        raise TypeError("canonical data value must remain a mapping")\n    return {"v": version, "value": dict(persisted)}\n'''
    text = replace_once(text, old, new, "envelope persistence boundary")

    old = '''    if payload_transform is not None:\n        payload = payload_transform(payload)\n    return _decode_domain(payload, target, codec)\n'''
    new = '''    if payload_transform is not None:\n        payload = payload_transform(payload)\n    normalized = _normalize_persisted_value(payload, codec)\n    return _decode_domain(normalized, target, codec)\n'''
    text = replace_once(text, old, new, "enveloped decode normalization")

    old = '''    payload = envelope.value.get("payload")\n    if payload is None:\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n    yield from _iter_runtime_object_refs(payload, default_domain, codec)\n'''
    new = '''    payload = envelope.value.get("payload")\n    if payload is None:\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n    normalized = _normalize_persisted_value(payload, codec)\n    yield from _iter_runtime_object_refs(normalized, default_domain, codec)\n'''
    text = replace_once(text, old, new, "object ref persistence normalization")

    old = '''    payload = envelope.value["payload"]\n    if payload is None:\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n    return _decode_domain(payload, target, codec)\n'''
    new = '''    payload = envelope.value["payload"]\n    if payload is None:\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n    normalized = _normalize_persisted_value(payload, codec)\n    return _decode_domain(normalized, target, codec)\n'''
    text = replace_once(text, old, new, "step persistence normalization")

    old = '''    if set(_V1_SCHEMA_FINGERPRINTS) != dataclass_wire_ids:\n        raise RuntimeError(\n            "GA v1 schema fingerprint manifest does not match domain types"\n        )\n'''
    new = '''    if set(_V1_SCHEMA_FINGERPRINTS) != dataclass_wire_ids:\n        raise RuntimeError(\n            "GA v1 schema fingerprint manifest does not match domain types"\n        )\n    contracts = _DATACLASS_PERSISTENCE_BY_VERSION.get(1)\n    if contracts is None or set(contracts) != dataclass_wire_ids:\n        raise RuntimeError("GA v1 persistence contracts do not match domain types")\n    for wire_id, contract in contracts.items():\n        revisions = tuple(sorted(contract.fingerprints))\n        if not revisions or revisions != tuple(range(1, revisions[-1] + 1)):\n            raise RuntimeError(f"GA v1 persistence revisions are invalid: {wire_id}")\n        if (\n            contract.legacy_revision is not None\n            and contract.legacy_revision not in contract.fingerprints\n        ):\n            raise RuntimeError(f"GA v1 legacy revision is invalid: {wire_id}")\n        expected_upgrades = set(range(1, contract.current_revision))\n        if set(contract.upgrades) != expected_upgrades:\n            raise RuntimeError(f"GA v1 persistence upgrades are incomplete: {wire_id}")\n        if (\n            contract.fingerprints[contract.current_revision]\n            != _V1_SCHEMA_FINGERPRINTS[wire_id]\n        ):\n            raise RuntimeError(f"GA v1 current fingerprint is inconsistent: {wire_id}")\n'''
    text = replace_once(text, old, new, "codec validation")

    CODEC.write_text(text, encoding="utf-8")


def patch_migration() -> None:
    text = MIGRATION.read_text(encoding="utf-8")
    old = '''    payload = value.get("payload")\n    if not isinstance(payload, Mapping):\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n    if set(payload) != {"$dataclass", "fields"} or payload.get("$dataclass") != wire_id:\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n    raw_fields = payload.get("fields")\n    if not isinstance(raw_fields, Mapping):\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n    return raw_fields\n'''
    new = '''    payload = value.get("payload")\n    return _persisted_dataclass_fields(payload, wire_id)\n'''
    text = replace_once(text, old, new, "migration root dataclass parser")

    old = '''def _nested_dataclass_fields(value: object, wire_id: str) -> Mapping[str, object]:\n    if not isinstance(value, Mapping):\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n    if set(value) != {"$dataclass", "fields"} or value.get("$dataclass") != wire_id:\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n    raw_fields = value.get("fields")\n    if not isinstance(raw_fields, Mapping):\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n    return raw_fields\n'''
    new = '''def _persisted_dataclass_fields(\n    value: object,\n    wire_id: str,\n) -> Mapping[str, object]:\n    if not isinstance(value, Mapping):\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n    keys = set(value)\n    if keys == {"$dataclass", "fields"}:\n        pass\n    elif keys == {"$dataclass", "schema", "fields"}:\n        schema = value.get("schema")\n        if isinstance(schema, bool) or not isinstance(schema, int) or schema < 1:\n            raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n        if schema != 1:\n            raise AIError(ErrorCode.STORAGE_VERSION_UNSUPPORTED)\n    else:\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n    if value.get("$dataclass") != wire_id:\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n    raw_fields = value.get("fields")\n    if not isinstance(raw_fields, Mapping):\n        raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n    return raw_fields\n\n\ndef _nested_dataclass_fields(value: object, wire_id: str) -> Mapping[str, object]:\n    return _persisted_dataclass_fields(value, wire_id)\n'''
    text = replace_once(text, old, new, "migration nested dataclass parser")

    old = '''def _is_current_binding(value: object) -> bool:\n    if not isinstance(value, Mapping):\n        return False\n    try:\n        AgentBindingSnapshot.from_payload(value)\n    except AIError:\n        return False\n    return True\n'''
    new = '''def _is_current_binding(value: object) -> bool:\n    if not isinstance(value, Mapping):\n        return False\n    try:\n        AgentBindingSnapshot.from_payload(value)\n    except AIError as error:\n        if error.code is ErrorCode.STORAGE_VERSION_UNSUPPORTED:\n            raise\n        return False\n    return True\n'''
    text = replace_once(text, old, new, "binding version propagation")
    MIGRATION.write_text(text, encoding="utf-8")


def patch_binding() -> None:
    text = BINDING.read_text(encoding="utf-8")
    old = '''        version = value["version"]\n        revision = value["output_schema_revision"]\n        descriptors = value["local_runtime_capability_descriptors"]\n        if version != 1 or isinstance(version, bool):\n            raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n'''
    new = '''        version = value["version"]\n        revision = value["output_schema_revision"]\n        descriptors = value["local_runtime_capability_descriptors"]\n        if isinstance(version, bool) or not isinstance(version, int) or version < 1:\n            raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n        if version != 1:\n            raise AIError(ErrorCode.STORAGE_VERSION_UNSUPPORTED)\n'''
    text = replace_once(text, old, new, "snapshot version semantics")
    BINDING.write_text(text, encoding="utf-8")


def write_build_helper() -> None:
    BUILD.write_text('''#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""Build-time validation for the Runtime persistence compatibility contract."""\n\nfrom __future__ import annotations\n\nimport argparse\nimport json\nfrom collections.abc import Mapping\nfrom pathlib import Path\nfrom typing import cast\n\nfrom linktools.ai.core import JsonValue\nfrom linktools.ai.runtime.state._codec import _runtime_persistence_manifest\n\n\ndef load_manifest(path: str | Path) -> dict[str, JsonValue]:\n    value = json.loads(Path(path).read_text(encoding="utf-8"))\n    if not isinstance(value, dict):\n        raise ValueError("runtime persistence manifest must be an object")\n    return cast("dict[str, JsonValue]", value)\n\n\ndef validate_runtime_persistence_manifest(\n    manifest: Mapping[str, JsonValue],\n) -> tuple[str, ...]:\n    expected = _runtime_persistence_manifest()\n    return () if dict(manifest) == expected else (\n        "runtime persistence manifest does not match the current codec contract",\n    )\n\n\ndef validate_append_only(\n    baseline: Mapping[str, JsonValue],\n    candidate: Mapping[str, JsonValue],\n) -> tuple[str, ...]:\n    errors: list[str] = []\n    if baseline.get("wire_version") != candidate.get("wire_version"):\n        errors.append("wire_version changed")\n\n    baseline_dataclasses = baseline.get("dataclasses")\n    candidate_dataclasses = candidate.get("dataclasses")\n    if not isinstance(baseline_dataclasses, Mapping) or not isinstance(\n        candidate_dataclasses, Mapping\n    ):\n        return tuple((*errors, "dataclasses manifest is invalid"))\n    for wire_id, raw_baseline in baseline_dataclasses.items():\n        raw_candidate = candidate_dataclasses.get(wire_id)\n        if not isinstance(raw_baseline, Mapping) or not isinstance(\n            raw_candidate, Mapping\n        ):\n            errors.append(f"historical dataclass removed: {wire_id}")\n            continue\n        if raw_baseline.get("legacy_revision") != raw_candidate.get(\n            "legacy_revision"\n        ):\n            errors.append(f"legacy revision changed: {wire_id}")\n        baseline_revisions = raw_baseline.get("revisions")\n        candidate_revisions = raw_candidate.get("revisions")\n        if not isinstance(baseline_revisions, Mapping) or not isinstance(\n            candidate_revisions, Mapping\n        ):\n            errors.append(f"revision manifest is invalid: {wire_id}")\n            continue\n        for revision, fingerprint in baseline_revisions.items():\n            if candidate_revisions.get(revision) != fingerprint:\n                errors.append(\n                    f"historical revision changed: {wire_id}@{revision}"\n                )\n\n    baseline_enums = baseline.get("enums")\n    candidate_enums = candidate.get("enums")\n    if not isinstance(baseline_enums, Mapping) or not isinstance(\n        candidate_enums, Mapping\n    ):\n        errors.append("enum manifest is invalid")\n    else:\n        for wire_id, raw_values in baseline_enums.items():\n            candidate_values = candidate_enums.get(wire_id)\n            if not isinstance(raw_values, list) or not isinstance(\n                candidate_values, list\n            ):\n                errors.append(f"historical enum removed: {wire_id}")\n                continue\n            if not set(raw_values).issubset(candidate_values):\n                errors.append(f"historical enum values removed: {wire_id}")\n\n    baseline_external = baseline.get("external")\n    candidate_external = candidate.get("external")\n    if not isinstance(baseline_external, Mapping) or not isinstance(\n        candidate_external, Mapping\n    ):\n        errors.append("external manifest is invalid")\n    else:\n        for name, value in baseline_external.items():\n            if candidate_external.get(name) != value:\n                errors.append(f"historical external contract changed: {name}")\n    return tuple(errors)\n\n\ndef _default_manifest() -> Path:\n    return Path(__file__).with_name("matrix") / "runtime-persistence-v1.json"\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--manifest", type=Path, default=_default_manifest())\n    parser.add_argument("--baseline", type=Path)\n    args = parser.parse_args()\n    candidate = load_manifest(args.manifest)\n    errors = list(validate_runtime_persistence_manifest(candidate))\n    if args.baseline is not None:\n        errors.extend(validate_append_only(load_manifest(args.baseline), candidate))\n    for error in errors:\n        print(error)\n    return 1 if errors else 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n\n\n__all__ = [\n    "load_manifest",\n    "validate_append_only",\n    "validate_runtime_persistence_manifest",\n]\n''', encoding="utf-8")


def write_test() -> None:
    TEST.write_text('''#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""Systemic compatibility contract for Runtime persisted dataclasses."""\n\nimport copy\nimport json\nfrom pathlib import Path\n\nimport pytest\n\nfrom linktools.ai.errors import AIError, ErrorCode\nfrom linktools.ai.runtime.state._codec import (\n    _CURRENT_CODEC,\n    _DataclassPersistenceContract,\n    _apply_persisted_upgrades,\n    _decode_enveloped_domain,\n    _decode_step_envelope,\n    _encode_step_envelope,\n    _runtime_persistence_manifest,\n    decode_domain,\n    encode_domain,\n    encode_envelope,\n    wire_type_id,\n)\nfrom linktools.ai.runtime.state._contracts import ConversationCursor\nfrom linktools.ai.agent import AgentBindingSnapshot\nfrom linktools.ai.agent._output import bind_output\nfrom linktools.ai.spec import AgentSpec\nfrom pydantic_ai_harness.step_persistence import RunRecord\nfrom datetime import datetime, timezone\n\n\ndef _legacy_cursor_envelope() -> dict[str, object]:\n    return {\n        "v": 1,\n        "value": {\n            "type": "conversation_cursor",\n            "payload": {\n                "$dataclass": "conversation_cursor",\n                "fields": {\n                    "step_run_id": "run",\n                    "history_id": None,\n                    "message_count": 0,\n                },\n            },\n        },\n    }\n\n\ndef test_semantic_encoding_remains_unversioned_and_byte_stable() -> None:\n    cursor = ConversationCursor("run", None, 0)\n    assert encode_domain(cursor) == {\n        "$dataclass": "conversation_cursor",\n        "fields": {\n            "step_run_id": "run",\n            "history_id": None,\n            "message_count": 0,\n        },\n    }\n    assert decode_domain(encode_domain(cursor), ConversationCursor) == cursor\n\n\ndef test_persistence_envelope_tags_dataclass_schema_without_changing_wire_major() -> None:\n    cursor = ConversationCursor("run", None, 0)\n    envelope = encode_envelope(\n        {"type": wire_type_id(cursor), "payload": encode_domain(cursor)}\n    )\n    assert envelope["v"] == 1\n    payload = envelope["value"]["payload"]\n    assert payload["$dataclass"] == "conversation_cursor"\n    assert payload["schema"] == 1\n    assert set(payload) == {"$dataclass", "schema", "fields"}\n    assert _decode_enveloped_domain(envelope, ConversationCursor) == cursor\n\n\ndef test_legacy_unversioned_v1_remains_readable() -> None:\n    envelope = _legacy_cursor_envelope()\n    assert _decode_enveloped_domain(envelope, ConversationCursor) == ConversationCursor(\n        "run", None, 0\n    )\n\n\ndef test_unknown_schema_is_unsupported_but_malformed_known_schema_is_integrity() -> None:\n    envelope = encode_envelope(\n        {\n            "type": "conversation_cursor",\n            "payload": encode_domain(ConversationCursor("run", None, 0)),\n        }\n    )\n    future = copy.deepcopy(envelope)\n    future["value"]["payload"]["schema"] = 99\n    with pytest.raises(AIError) as raised:\n        _decode_enveloped_domain(future, ConversationCursor)\n    assert raised.value.code is ErrorCode.STORAGE_VERSION_UNSUPPORTED\n\n    malformed = copy.deepcopy(envelope)\n    malformed["value"]["payload"]["fields"].pop("history_id")\n    with pytest.raises(AIError) as raised:\n        _decode_enveloped_domain(malformed, ConversationCursor)\n    assert raised.value.code is ErrorCode.STORAGE_INTEGRITY_ERROR\n\n    for invalid in (True, 0, -1, "1"):\n        malformed_revision = copy.deepcopy(envelope)\n        malformed_revision["value"]["payload"]["schema"] = invalid\n        with pytest.raises(AIError) as raised:\n            _decode_enveloped_domain(malformed_revision, ConversationCursor)\n        assert raised.value.code is ErrorCode.STORAGE_INTEGRITY_ERROR\n\n\ndef test_adjacent_upgrade_chain_is_explicit_and_pure() -> None:\n    def one_to_two(raw, _codec):\n        assert set(raw) == {"old"}\n        return {"new": raw["old"]}\n\n    contract = _DataclassPersistenceContract(\n        fingerprints={1: "a", 2: "b"},\n        upgrades={1: one_to_two},\n        legacy_revision=1,\n    )\n    source = {"old": "value"}\n    assert _apply_persisted_upgrades(source, 1, contract, _CURRENT_CODEC) == {\n        "new": "value"\n    }\n    assert source == {"old": "value"}\n\n\ndef test_step_persistence_writes_schema_and_reads_legacy_unversioned() -> None:\n    now = datetime(2026, 1, 1, tzinfo=timezone.utc)\n    run = RunRecord(\n        run_id="run",\n        conversation_id="conversation",\n        parent_run_id=None,\n        agent_name="agent",\n        metadata={},\n        started_at=now,\n    )\n    current = _encode_step_envelope(run)\n    assert current["value"]["payload"]["schema"] == 1\n    assert _decode_step_envelope(current) == run\n\n    legacy = copy.deepcopy(current)\n    legacy["value"]["payload"].pop("schema")\n    assert _decode_step_envelope(legacy) == run\n\n\ndef _binding_snapshot_payload() -> dict[str, object]:\n    output = bind_output()\n    snapshot = AgentBindingSnapshot(\n        version=1,\n        agent_spec=AgentSpec("agent", 1, "default"),\n        agent_digest="b" * 64,\n        output_type_module=output.value_type.__module__,\n        output_type_qualname=output.value_type.__qualname__,\n        output_schema_id=output.schema_id,\n        output_schema_revision=output.schema_revision,\n        output_schema_fingerprint=output.schema_fingerprint,\n        local_runtime_capability_descriptors=(),\n        binding_digest="a" * 64,\n    )\n    return snapshot.to_payload()\n\n\ndef test_agent_binding_snapshot_future_version_is_unsupported() -> None:\n    payload = _binding_snapshot_payload()\n    assert AgentBindingSnapshot.from_payload(payload).version == 1\n    future = dict(payload)\n    future["version"] = 2\n    with pytest.raises(AIError) as raised:\n        AgentBindingSnapshot.from_payload(future)\n    assert raised.value.code is ErrorCode.STORAGE_VERSION_UNSUPPORTED\n    malformed = dict(payload)\n    malformed["version"] = True\n    with pytest.raises(AIError) as raised:\n        AgentBindingSnapshot.from_payload(malformed)\n    assert raised.value.code is ErrorCode.STORAGE_INTEGRITY_ERROR\n\n\ndef test_checked_in_runtime_persistence_manifest_matches_codec_contract() -> None:\n    path = (\n        Path(__file__).resolve().parents[2]\n        / "linktools-ai/scripts/build/matrix/runtime-persistence-v1.json"\n    )\n    assert json.loads(path.read_text(encoding="utf-8")) == _runtime_persistence_manifest()\n''', encoding="utf-8")


def write_manifest() -> None:
    import sys
    sys.path.insert(0, str(ROOT / "linktools-ai/src"))
    from linktools.ai.runtime.state._codec import _runtime_persistence_manifest
    MANIFEST.write_text(
        json.dumps(_runtime_persistence_manifest(), indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def main() -> None:
    patch_codec()
    patch_migration()
    patch_binding()
    write_build_helper()
    write_test()
    write_manifest()
    print("runtime persistence compatibility implementation applied")


if __name__ == "__main__":
    main()
